import json
import os

import numpy as np
import jax
import jax.numpy as jnp
from jax import lax


def task_basic_reduce(path: str) -> jnp.ndarray:
    x = jnp.array(np.load(path))
    return jnp.mean(x, axis=1)


def task_map_square(path: str) -> jnp.ndarray:
    x = jnp.array(np.load(path))
    return jnp.square(x)


def task_grad_logistic(path: str) -> jnp.ndarray:
    data = np.load(path)
    X = jnp.array(data["x"])
    y = jnp.array(data["y"])
    w = jnp.array(data["w"])

    def loss_fn(w_vec: jnp.ndarray) -> jnp.ndarray:
        z = y * (X @ w_vec)
        return jnp.mean(jnp.logaddexp(0.0, -z))

    grad_fn = jax.grad(loss_fn)
    return grad_fn(w)


def task_scan_rnn(path: str) -> jnp.ndarray:
    data = np.load(path)
    seq = jnp.array(data["seq"])
    init = jnp.array(data["init"])
    Wx = jnp.array(data["Wx"])
    Wh = jnp.array(data["Wh"])
    b = jnp.array(data["b"])

    def step(h: jnp.ndarray, x_t: jnp.ndarray):
        h = jnp.tanh(Wx @ x_t + Wh @ h + b)
        return h, h

    _, hs = lax.scan(step, init, seq)
    return hs


def task_jit_mlp(path: str) -> jnp.ndarray:
    data = np.load(path)
    X = jnp.array(data["X"])
    W1 = jnp.array(data["W1"])
    b1 = jnp.array(data["b1"])
    W2 = jnp.array(data["W2"])
    b2 = jnp.array(data["b2"])

    def mlp(x: jnp.ndarray, w1: jnp.ndarray, b1_: jnp.ndarray, w2: jnp.ndarray, b2_: jnp.ndarray) -> jnp.ndarray:
        h = jnp.maximum(0.0, x @ w1 + b1_)
        return h @ w2 + b2_

    mlp_jit = jax.jit(mlp)
    return mlp_jit(X, W1, b1, W2, b2)


TASKS = {
    "basic_reduce": task_basic_reduce,
    "map_square": task_map_square,
    "grad_logistic": task_grad_logistic,
    "scan_rnn": task_scan_rnn,
    "jit_mlp": task_jit_mlp,
}


def main() -> None:
    with open("problem.json", "r", encoding="utf-8") as f:
        problems = json.load(f)

    for problem in problems:
        task_id = problem["id"]
        input_path = problem["input"]
        output_path = problem["output"]
        func = TASKS.get(task_id)
        if func is None:
            raise ValueError(f"Unknown task id: {task_id}")

        result = func(input_path)
        output_dir = os.path.dirname(output_path)
        if output_dir:
            os.makedirs(output_dir, exist_ok=True)
        np.save(output_path, np.array(result))


if __name__ == "__main__":
    main()
